/** Actual platform edits/deletions, configured-item installation and failures after superclass mutation. */
@EventBusSubscriber(modid="vandorlabs")
public final class LightLoadGuardChecks {
 private static final BlockPos BASE=new BlockPos(7056,90,7056);private static final NativeLightBlock[] BLOCKS=new NativeLightBlock[3];private static BlockEntityType<NativeLightEntity> TYPE;private static AttachmentType<String> attachment,transientAttachment,flakyAttachment;private static int attachmentReads;private static int checks;private static boolean refusedRestore;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("light-load-guard-");}private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Light load guard: "+text);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(var kind:NativeLightBlock.Kind.values()){int i=kind.ordinal();BLOCKS[i]=NativeLightBlock.create(kind,BlockBehaviour.Properties.of().strength(5,6),()->TYPE);h.register(id(i),BLOCKS[i]);}});event.register(Registries.ITEM,h->{for(int i=0;i<3;i++)h.register(id(i),new GuardItem(BLOCKS[i]));});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeLightEntity>of((p,s)->new NativeLightEntity(TYPE,p,s,com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE),BLOCKS).build(null);h.register(ResourceLocation.parse("vandorlabs:light_guard_fixture"),TYPE);});event.register(net.neoforged.neoforge.registries.NeoForgeRegistries.Keys.ATTACHMENT_TYPES,h->{attachment=AttachmentType.builder(()->"default").serialize(Codec.STRING).build();h.register(ResourceLocation.parse("vandorlabs:light_guard_attachment"),attachment);transientAttachment=AttachmentType.builder(()->"transient").build();h.register(ResourceLocation.parse("vandorlabs:light_guard_transient"),transientAttachment);flakyAttachment=AttachmentType.builder(()->"default").serialize(new net.neoforged.neoforge.attachment.IAttachmentSerializer<Tag,String>(){public String read(net.neoforged.neoforge.attachment.IAttachmentHolder owner,Tag tag,HolderLookup.Provider registries){attachmentReads++;if(tag.getAsString().equals("throw"))throw new IllegalStateException("fixture swallowed attachment decode");return tag.getAsString().equals("null")?null:tag.getAsString();}public Tag write(String value,HolderLookup.Provider registries){return value==null?null:StringTag.valueOf(value);}}).build();h.register(ResourceLocation.parse("vandorlabs:light_guard_flaky"),flakyAttachment);});}}
 private static final class GuardItem extends NativeLightItem {GuardItem(NativeLightBlock block){super(block,new Item.Properties());}@Override protected boolean stage(Level world,BlockPos pos,net.minecraft.world.level.block.state.BlockState state){boolean placed=super.stage(world,pos,state);return refusedRestore?false:placed;}@Override protected boolean restore(Level world,BlockPos pos,net.minecraft.world.level.block.state.BlockState old){return refusedRestore?false:super.restore(world,pos,old);}}
 private static ResourceLocation id(int i){return ResourceLocation.fromNamespaceAndPath("vandorlabs","light_guard_fixture_"+i);}
 private static CompoundTag data(boolean platform){var tag=new CompoundTag();tag.putInt("LightLevel",7);tag.putInt("LightTrigger",0);tag.putString("ForeignRoot","retain:opaque");if(platform){var nativeData=new CompoundTag();nativeData.putString("OriginalNative","from-load");tag.put("NeoForgeData",nativeData);var attachments=new CompoundTag();attachments.putString("vandorlabs:light_guard_attachment","from-load");tag.put("neoforge:attachments",attachments);var components=new CompoundTag();components.putString("minecraft:custom_name","from-load");tag.put("components",components);}return tag;}
 private static NativeLightEntity put(ServerLevel world,BlockPos pos,int family){world.getChunkAt(pos);world.setBlock(pos,BLOCKS[family].defaultBlockState(),18);return (NativeLightEntity)world.getBlockEntity(pos);}
 private static void component(NativeLightEntity tile,String name){tile.setComponents(DataComponentMap.builder().set(DataComponents.CUSTOM_NAME,Component.literal(name)).build());}
 private static final class PartialFailureTag extends CompoundTag {PartialFailureTag(CompoundTag raw){merge(raw);}@Override public CompoundTag copy(){return new PartialFailureTag(super.copy());}@Override public CompoundTag getCompound(String key){return key.equals("neoforge:attachments")?new ThrowingAttachments():super.getCompound(key);}}
 private static final class ThrowingAttachments extends CompoundTag {@Override public Set<String> getAllKeys(){throw new IllegalStateException("fixture failure after Light platform persistent installation");}}
 private static void write(ServerLevel world){var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new UUID(0,702),"LightGuard"));actor.setGameMode(GameType.SURVIVAL);for(int family=0;family<3;family++){var pos=BASE.east(family*8);var tile=put(world,pos,family);var input=data(true);var original=input.copy();tile.loadWithComponents(input,world.registryAccess());need(!tile.inert()&&tile.components().get(DataComponents.CUSTOM_NAME).getString().equals("from-load"),"valid platform component loads family="+family);tile.getPersistentData().putString("LiveEdit","current");tile.setData(attachment,"current");component(tile,"current");need(input.equals(original),"superclass data cannot alias input");var saved=tile.saveWithoutMetadata(world.registryAccess());need(saved.getCompound("NeoForgeData").getString("LiveEdit").equals("current")&&saved.getCompound("neoforge:attachments").getString("vandorlabs:light_guard_attachment").equals("current"),"live platform edits replace original serialized fields");for(String key:List.copyOf(tile.getPersistentData().getAllKeys()))tile.getPersistentData().remove(key);tile.removeData(attachment);tile.setComponents(DataComponentMap.EMPTY);saved=tile.saveWithoutMetadata(world.registryAccess());need(saved.getCompound("NeoForgeData").isEmpty()&&!saved.getCompound("neoforge:attachments").contains("vandorlabs:light_guard_attachment")&&!saved.getCompound("components").contains("minecraft:custom_name"),"valid platform deletions do not resurrect stale original attachments/components");
  tile.loadWithComponents(data(true),world.registryAccess());tile.getPersistentData().putString("LiveEdit","item-current");tile.setData(attachment,"item-current");component(tile,"item-current");var picked=NativeLightItem.pick(BLOCKS[family].asItem(),tile);var item=NativeLightItem.configuration(picked);need(item.getCompound("NeoForgeData").getString("LiveEdit").equals("item-current")&&item.getCompound("neoforge:attachments").getString("vandorlabs:light_guard_attachment").equals("item-current"),"configured pick serializes current platform owner");var destination=pos.south(3);world.setBlock(destination,Blocks.AIR.defaultBlockState(),18);world.setBlock(destination.below(),Blocks.STONE.defaultBlockState(),18);actor.setPos(destination.getX()+.5,destination.getY()+1,destination.getZ()-2);actor.setItemInHand(InteractionHand.MAIN_HAND,picked);need(picked.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(destination),Direction.UP,destination.below(),false))).consumesAction()&&picked.isEmpty(),"actual configured item transfers one owner");var placed=(NativeLightEntity)world.getBlockEntity(destination);need(placed!=null&&placed.getPersistentData().getString("LiveEdit").equals("item-current")&&placed.getData(attachment).equals("item-current")&&placed.components().get(DataComponents.CUSTOM_NAME).getString().equals("item-current"),"prepared placement installs actual platform data before publication");
  var faultPos=pos.south(6);world.setBlock(faultPos,Blocks.AIR.defaultBlockState(),18);world.setBlock(faultPos.below(),Blocks.STONE.defaultBlockState(),18);var faultStack=NativeLightItem.pick(BLOCKS[family].asItem(),placed);faultStack.setCount(2);var frozen=NativeLightItem.configuration(faultStack);actor.setPos(faultPos.getX()+.5,faultPos.getY()+1,faultPos.getZ()-2);actor.setItemInHand(InteractionHand.MAIN_HAND,faultStack);boolean threw=false;refusedRestore=true;try{faultStack.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(faultPos),Direction.UP,faultPos.below(),false)));}catch(RuntimeException expectedFailure){threw=true;}finally{refusedRestore=false;}var recovery=(NativeLightEntity)world.getBlockEntity(faultPos);var recovered=recovery.saveWithoutMetadata(world.registryAccess());need(threw&&faultStack.getCount()==1&&recovery.inert()&&recovered.getBoolean(NativeLightItem.PLACEMENT_RECOVERY),"refused rollback retains one consumed inert platform owner");for(String key:List.of("NeoForgeData","neoforge:attachments","components"))need(java.util.Objects.equals(recovered.get(key),frozen.get(key)),"failed rollback retains complete prepared platform bytes key="+key);
  for(boolean platform:new boolean[]{false,true}){tile.loadWithComponents(data(true),world.registryAccess());var failed=data(platform);failed.putInt("NativeLightSchema",99);original=failed.copy();tile.loadWithComponents(failed,world.registryAccess());tile.getPersistentData().putString("AfterFailure","must-not-save");tile.setData(attachment,"must-not-save");component(tile,"must-not-save");need(tile.inert()&&!tile.isChannelMemberActive()&&tile.visual().emitted()==0,"future schema remains inert");need(failed.equals(original)&&tile.saveWithoutMetadata(world.registryAccess()).equals(original),"full failed platform snapshot survives attempted live edits family="+family+" platform="+platform);need(!tile.getUpdateTag(world.registryAccess()).contains("NeoForgeData")&&!tile.getUpdateTag(world.registryAccess()).contains("components")&&!tile.getUpdateTag(world.registryAccess()).contains("neoforge:attachments"),"public update excludes platform data");}
  for(int kind=0;kind<4;kind++){var unsupported=data(true);if(kind==0)unsupported.putString("neoforge:attachments","opaque:future-envelope");else{var fields=new CompoundTag();fields.putString(kind==1?"missing:light_attachment":kind==2?"!bad-key":"vandorlabs:light_guard_transient","opaque:attachment");unsupported.put("neoforge:attachments",fields);}tile.loadWithComponents(unsupported,world.registryAccess());need(tile.inert()&&tile.saveWithoutMetadata(world.registryAccess()).equals(unsupported),"unsupported attachment remains opaque and inert kind="+kind);var refused=pos.north(3);world.setBlock(refused,Blocks.AIR.defaultBlockState(),18);world.setBlock(refused.below(),Blocks.STONE.defaultBlockState(),18);var stack=new ItemStack(BLOCKS[family].asItem(),2);var custom=new CompoundTag();custom.put(NativeLightItem.CONFIGURATION,unsupported.copy());stack.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(custom));actor.setPos(refused.getX()+.5,refused.getY()+1,refused.getZ()-2);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);need(!stack.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(refused),Direction.UP,refused.below(),false))).consumesAction()&&stack.getCount()==2&&world.getBlockState(refused).isAir(),"unsupported attachment item refuses before mutation/consumption kind="+kind);}
  for(String mode:List.of("throw","null")){tile.loadWithComponents(data(true),world.registryAccess());tile.setData(flakyAttachment,"old-live");var failed=data(true);failed.getCompound("neoforge:attachments").putString("vandorlabs:light_guard_flaky",mode);int reads=attachmentReads;tile.loadWithComponents(failed,world.registryAccess());component(tile,"must-not-graft");need(tile.inert()&&attachmentReads==reads+1&&tile.saveWithoutMetadata(world.registryAccess()).equals(failed),"caught/null decode fails inert exactly once even with stale old map mode="+mode);}
  var unknown=data(true);unknown.getCompound("components").putString("missing:light_component","opaque:unknown-component");tile.loadWithComponents(unknown,world.registryAccess());component(tile,"must-not-graft");need(tile.inert()&&tile.saveWithoutMetadata(world.registryAccess()).equals(unknown),"unknown component map remains wholly opaque and inert");
  tile.loadWithComponents(data(true),world.registryAccess());tile.getPersistentData().putString("OriginalNative","before-partial");var partial=data(true);partial.putInt("LightLevel",3);tile.loadWithComponents(new PartialFailureTag(partial),world.registryAccess());need(tile.inert()&&tile.getPersistentData().getString("OriginalNative").equals("from-load"),"failure occurs after actual superclass persistent installation");need(tile.settings().light().configuredLevel!=3,"partially decoded Light choices never install");component(tile,"after-partial");need(tile.saveWithoutMetadata(world.registryAccess()).equals(partial),"partial superclass/components cannot overwrite retained original");
  var failed=data(true);failed.putInt("NativeLightSchema",99);tile.loadWithComponents(failed,world.registryAccess());world.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);world.setChunkForced(destination.getX()>>4,destination.getZ()>>4,true);world.setChunkForced(faultPos.getX()>>4,faultPos.getZ()>>4,true);
 }}
 private static void read(ServerLevel world){for(int family=0;family<3;family++){var pos=BASE.east(family*8);world.getChunkAt(pos);var tile=(NativeLightEntity)world.getBlockEntity(pos);need(tile!=null&&tile.inert(),"future owner remains inert after restart");var saved=tile.saveWithoutMetadata(world.registryAccess());for(String key:List.of("id","x","y","z"))saved.remove(key);if(saved.contains("keepPacked")){need(saved.contains("keepPacked",Tag.TAG_BYTE)&&!saved.getBoolean("keepPacked"),"vanilla storage flag typed false");saved.remove("keepPacked");}var expected=data(true);expected.putInt("NativeLightSchema",99);need(saved.equals(expected),"full original snapshot survives whole-process restart family="+family);var placed=(NativeLightEntity)world.getBlockEntity(pos.south(3));need(placed!=null&&!placed.inert()&&placed.getPersistentData().getString("LiveEdit").equals("item-current")&&placed.getData(attachment).equals("item-current")&&placed.components().get(DataComponents.CUSTOM_NAME).getString().equals("item-current"),"placed item platform data survives restart");var recovery=(NativeLightEntity)world.getBlockEntity(pos.south(6));need(recovery!=null&&recovery.inert()&&recovery.saveWithoutMetadata(world.registryAccess()).getBoolean(NativeLightItem.PLACEMENT_RECOVERY)&&recovery.recoverySnapshot().getCompound("NeoForgeData").getString("LiveEdit").equals("item-current"),"failed rollback complete platform owner survives restart");}}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{var world=event.getServer().overworld();boolean read=System.getProperty("vandorlabs.transmitterPhase").endsWith("read");if(read)read(world);else write(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][light-load-guard] "+(read?"read":"write")+" PASS checks="+checks);}catch(Throwable failure){System.err.println("[vandorlabs][light-load-guard] FAIL "+failure);failure.printStackTrace();}finally{event.getServer().halt(false);}}
}
